{
  "XHTML": "<ion-content>
  <ion-grid>
    <ion-row>
      <ion-col *ngFor="let header of this?.tableHeaders">
        {{header}}
      </ion-col>
    </ion-row>
    <ng-container *ngFor="let item of this?.jsonData">
      <ion-row>
        <ion-col *ngFor="let key of this?.tableHeaders">
          {{item[key]}}
        </ion-col>
      </ion-row>
    </ng-container>
  </ion-grid>
</ion-content>",
  "typescript": "import { Component } from '@angular/core';

@Component({
  selector: 'app-json-table',
  templateUrl: './json-table.component.html',
  styleUrls: ['./json-table.component.scss'],
})
export class JsonTableComponent {
  /*Begin_c8o_CompDeclaration*/
  jsonData: any[] = [];
  tableHeaders: string[] = [];
  /*End_c8o_CompDeclaration*/

  /*Begin_c8o_CompConstructor*/
  constructor() {
    // Example JSON data
    this.jsonData = [
      { id: 1, name: 'Alice', age: 30 },
      { id: 2, name: 'Bob', age: 25 },
      { id: 3, name: 'Charlie', age: 35 }
    ];
    if (this.jsonData.length > 0) {
      this.tableHeaders = Object.keys(this.jsonData[0]);
    }
  }
  /*End_c8o_CompConstructor*/

  /*Begin_c8o_CompFunction*/
  // Additional methods can be added here if needed
  /*End_c8o_CompFunction*/
}
",
  "css": "ion-grid {
  width: 100%;
}

ion-row {
  border-bottom: 1px solid #ccc;
  padding: 8px 0;
}

ion-col {
  font-size: 14px;
  font-weight: 500;
  padding: 0 8px;
}

ion-row:first-child {
  font-weight: bold;
  background-color: #f0f0f0;
}
",
  "variables": {
    "jsonData": [
      { "id": 1, "name": "Alice", "age": 30 },
      { "id": 2, "name": "Bob", "age": 25 },
      { "id": 3, "name": "Charlie", "age": 35 }
    ],
    "tableHeaders": ["id", "name", "age"]
  },
  "explanation": "Le composant Angular Ionic affichera les données JSON dans un tableau utilisant ion-grid, ion-row, et ion-col d'Ionic. Les en-têtes du tableau sont générés dynamiquement à partir des clés du premier objet JSON. Chaque ligne du tableau affiche les valeurs correspondantes. Le CSS stylise le tableau pour une meilleure lisibilité."
}
